"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { formatUsd } from "@/lib/utils";

export function StartingBankrollCard({
  startingBankrollUsd,
  startingBankrollSetAt,
  onSet,
}: {
  startingBankrollUsd: number | null;
  startingBankrollSetAt: string | null;
  onSet: (amount: number) => void;
}) {
  const [draft, setDraft] = useState("");
  // Editing is only ever toggled explicitly (Edit/Save) — it must not be
  // seeded from startingBankrollUsd at mount, since that prop starts null
  // pre-hydration (before localStorage loads) even when a bankroll is
  // already saved, which previously made this card flash back to the edit
  // form on every reload.
  const [isEditingOverride, setIsEditingOverride] = useState(false);
  const showForm = startingBankrollUsd === null || isEditingOverride;

  function handleEdit() {
    setDraft(startingBankrollUsd?.toString() ?? "");
    setIsEditingOverride(true);
  }

  function handleSave() {
    const amount = Number(draft);
    if (!Number.isFinite(amount) || amount <= 0) return;
    onSet(amount);
    setIsEditingOverride(false);
  }

  if (!showForm) {
    return (
      <Card>
        <CardHeader className="flex-row items-center justify-between pb-0">
          <CardTitle>Starting bankroll</CardTitle>
          <Button size="sm" variant="ghost" onClick={handleEdit}>
            Edit
          </Button>
        </CardHeader>
        <CardContent className="pt-1">
          <div className="text-2xl font-semibold text-neutral-100">
            {formatUsd(startingBankrollUsd)}
          </div>
          {startingBankrollSetAt && (
            <div className="mt-1 text-xs text-neutral-500">
              Set {new Date(startingBankrollSetAt).toLocaleDateString()}
            </div>
          )}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Starting bankroll</CardTitle>
      </CardHeader>
      <CardContent className="flex items-end gap-2">
        <div className="flex flex-col gap-1">
          <label className="text-xs text-neutral-500" htmlFor="starting-bankroll">
            Amount ($)
          </label>
          <Input
            id="starting-bankroll"
            type="number"
            min={0}
            step="0.01"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="1000"
            className="w-36"
          />
        </div>
        <Button onClick={handleSave} disabled={!draft || Number(draft) <= 0}>
          Save
        </Button>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { formatUsd } from "@/lib/utils";
import { AlertTriangle, PlusCircle } from "lucide-react";
import type { Trade } from "@/lib/portfolio/types";

export function TradeForm({
  onAdd,
  availableBankrollUsd,
}: {
  onAdd: (trade: Trade) => void;
  /** Free cash not already committed to open trades — used to warn on over-staking. Null if no starting bankroll is set. */
  availableBankrollUsd: number | null;
}) {
  const [marketQuestion, setMarketQuestion] = useState("");
  const [outcome, setOutcome] = useState("");
  const [entryPriceCents, setEntryPriceCents] = useState("");
  const [stakeUsd, setStakeUsd] = useState("");
  const [polymarketUrl, setPolymarketUrl] = useState("");
  const [notes, setNotes] = useState("");

  const entryValid = Number(entryPriceCents) > 0 && Number(entryPriceCents) < 100;
  const stakeValid = Number(stakeUsd) > 0;
  const canSubmit = marketQuestion.trim().length > 0 && outcome.trim().length > 0 && entryValid && stakeValid;
  const exceedsAvailable =
    stakeValid && availableBankrollUsd !== null && Number(stakeUsd) > availableBankrollUsd;

  function handleSubmit() {
    if (!canSubmit) return;
    const trade: Trade = {
      id: crypto.randomUUID(),
      marketQuestion: marketQuestion.trim(),
      outcome: outcome.trim(),
      entryPriceCents: Number(entryPriceCents),
      stakeUsd: Number(stakeUsd),
      status: "open",
      exitPriceCents: null,
      currentPriceCents: null,
      polymarketUrl: polymarketUrl.trim() || null,
      notes: notes.trim() || null,
      openedAt: new Date().toISOString(),
      closedAt: null,
    };
    onAdd(trade);
    setMarketQuestion("");
    setOutcome("");
    setEntryPriceCents("");
    setStakeUsd("");
    setPolymarketUrl("");
    setNotes("");
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-neutral-200">Log a trade</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-3">
        <FormField label="Market question">
          <Input
            value={marketQuestion}
            onChange={(e) => setMarketQuestion(e.target.value)}
            placeholder="Will the Fed cut rates in September?"
          />
        </FormField>
        <FormField label="Outcome">
          <Input value={outcome} onChange={(e) => setOutcome(e.target.value)} placeholder="Yes" />
        </FormField>
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Entry price (¢)">
            <Input
              type="number"
              min={0.01}
              max={99.99}
              step="0.01"
              value={entryPriceCents}
              onChange={(e) => setEntryPriceCents(e.target.value)}
              placeholder="58"
            />
          </FormField>
          <FormField label="Stake ($)">
            <Input
              type="number"
              min={0.01}
              step="0.01"
              value={stakeUsd}
              onChange={(e) => setStakeUsd(e.target.value)}
              placeholder="100"
            />
          </FormField>
        </div>
        {exceedsAvailable && (
          <div className="flex items-start gap-1.5 rounded-md border border-amber-900/50 bg-amber-950/30 p-2 text-xs text-amber-300">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
            This stake ({formatUsd(Number(stakeUsd))}) exceeds your available bankroll of{" "}
            {formatUsd(availableBankrollUsd)}. You can still log it if that&apos;s what actually
            happened, but it means you&apos;re risking more than your tracked bankroll covers.
          </div>
        )}
        <FormField label="Polymarket URL (optional)">
          <Input
            value={polymarketUrl}
            onChange={(e) => setPolymarketUrl(e.target.value)}
            placeholder="https://polymarket.com/event/..."
          />
        </FormField>
        <FormField label="Notes (optional)">
          <Textarea rows={2} value={notes} onChange={(e) => setNotes(e.target.value)} />
        </FormField>
        <Button onClick={handleSubmit} disabled={!canSubmit}>
          <PlusCircle /> Add trade
        </Button>
      </CardContent>
    </Card>
  );
}

function FormField({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1">
      <label className="text-xs text-neutral-500">{label}</label>
      {children}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { TableCell, TableRow } from "@/components/ui/table";
import { computeTradePnl } from "@/lib/portfolio/calculations";
import { formatCents, formatUsd, safeExternalUrl } from "@/lib/utils";
import { ExternalLink, Trash2 } from "lucide-react";
import type { Trade, TradeStatus } from "@/lib/portfolio/types";

const STATUS_VARIANT: Record<TradeStatus, "default" | "danger" | "warning" | "secondary"> = {
  open: "warning",
  won: "default",
  lost: "danger",
  sold: "secondary",
};

export function TradeRow({
  trade,
  onUpdate,
  onDelete,
}: {
  trade: Trade;
  onUpdate: (id: string, patch: Partial<Trade>) => void;
  onDelete: (id: string) => void;
}) {
  const [mode, setMode] = useState<"none" | "sell" | "price">("none");
  const [inputValue, setInputValue] = useState("");

  const pnl = computeTradePnl(trade);
  const displayPnl = trade.status === "open" ? pnl.unrealizedPnl : pnl.realizedPnl;
  const safeUrl = safeExternalUrl(trade.polymarketUrl);

  function closeAs(status: "won" | "lost") {
    onUpdate(trade.id, { status, closedAt: new Date().toISOString() });
  }

  function confirmSell() {
    const cents = Number(inputValue);
    if (!Number.isFinite(cents) || cents < 0 || cents > 100) return;
    onUpdate(trade.id, { status: "sold", exitPriceCents: cents, closedAt: new Date().toISOString() });
    setMode("none");
    setInputValue("");
  }

  function confirmPrice() {
    const cents = Number(inputValue);
    if (!Number.isFinite(cents) || cents < 0 || cents > 100) return;
    onUpdate(trade.id, { currentPriceCents: cents });
    setMode("none");
    setInputValue("");
  }

  return (
    <TableRow>
      <TableCell className="max-w-56 truncate font-medium text-neutral-100" title={trade.marketQuestion}>
        {safeUrl ? (
          <a href={safeUrl} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 hover:text-emerald-400">
            {trade.marketQuestion} <ExternalLink className="h-3 w-3 shrink-0" />
          </a>
        ) : (
          trade.marketQuestion
        )}
      </TableCell>
      <TableCell>
        <Badge variant="outline">{trade.outcome}</Badge>
      </TableCell>
      <TableCell className="tabular-nums">{formatCents(trade.entryPriceCents / 100)}</TableCell>
      <TableCell className="tabular-nums">{formatUsd(trade.stakeUsd)}</TableCell>
      <TableCell className="tabular-nums text-neutral-400">{pnl.shares.toFixed(1)}</TableCell>
      <TableCell>
        <Badge variant={STATUS_VARIANT[trade.status]}>{trade.status}</Badge>
      </TableCell>
      <TableCell className={`tabular-nums ${displayPnl !== null && displayPnl >= 0 ? "text-emerald-400" : displayPnl !== null ? "text-red-400" : "text-neutral-500"}`}>
        {displayPnl === null ? "—" : formatUsd(displayPnl)}
      </TableCell>
      <TableCell>
        {trade.status === "open" ? (
          mode === "none" ? (
            <div className="flex flex-wrap gap-1">
              <Button size="sm" variant="secondary" onClick={() => closeAs("won")}>
                Won
              </Button>
              <Button size="sm" variant="secondary" onClick={() => closeAs("lost")}>
                Lost
              </Button>
              <Button size="sm" variant="outline" onClick={() => setMode("sell")}>
                Sell
              </Button>
              <Button size="sm" variant="ghost" onClick={() => setMode("price")}>
                Update price
              </Button>
              <Button size="sm" variant="ghost" onClick={() => onDelete(trade.id)} aria-label="Delete trade">
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>
          ) : (
            <div className="flex items-center gap-1">
              <Input
                type="number"
                min={0}
                max={100}
                step="0.01"
                autoFocus
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder={mode === "sell" ? "Exit ¢" : "Current ¢"}
                className="h-8 w-24"
              />
              <Button size="sm" onClick={mode === "sell" ? confirmSell : confirmPrice}>
                Confirm
              </Button>
              <Button size="sm" variant="ghost" onClick={() => setMode("none")}>
                Cancel
              </Button>
            </div>
          )
        ) : (
          <Button size="sm" variant="ghost" onClick={() => onDelete(trade.id)} aria-label="Delete trade">
            <Trash2 className="h-3.5 w-3.5" />
          </Button>
        )}
      </TableCell>
    </TableRow>
  );
}

