export function buildDemoResponse(options: AnalyzeRequestOptions): AnalyzeResponse {
  const positions = buildDemoPositions();
  const marketsByCondition = new Map(DEMO_MARKETS.map((m) => [m.conditionId!, m]));

  const positionsByWallet = new Map<string, NormalizedPosition[]>();
  for (const p of positions) {
    const list = positionsByWallet.get(p.wallet) ?? [];
    list.push(p);
    positionsByWallet.set(p.wallet, list);
  }

  const [w1, w2] = DEMO_WALLETS;
  const redeemsByWallet = new Map<string, RedeemSample[]>([
    // w1 recently redeemed two resolved markets — showcases the realized-signal boost.
    [w1, [
      { timestamp: NOW - 2 * 24 * HOUR, usdcSize: 1200 },
      { timestamp: NOW - 9 * 24 * HOUR, usdcSize: 480 },
    ]],
    [w2, [{ timestamp: NOW - 20 * 24 * HOUR, usdcSize: 150 }]],
  ]);

  const walletScores = scoreAllWallets(positionsByWallet, redeemsByWallet, NOW);
  const ideas = buildTradeIdeas(positions, walletScores, marketsByCondition, options, NOW);

  const walletResults: WalletLoadResult[] = DEMO_WALLETS.map((wallet) => ({
    wallet,
    status: "ok",
    positionCount: positionsByWallet.get(wallet)?.length ?? 0,
    filteredPositionCount: positionsByWallet.get(wallet)?.length ?? 0,
  }));

  const totalTrackedExposure = positions.reduce((sum, p) => sum + p.currentValue, 0);

  return {
    summary: {
      walletsRequested: DEMO_WALLETS.length,
      walletsAnalyzed: DEMO_WALLETS.length,
      walletsLoaded: DEMO_WALLETS.length,
      walletsFailed: 0,
      activePositionsFound: positions.length,
      activeMarketsFound: new Set(positions.map((p) => p.conditionId)).size,
      consensusIdeasFound: ideas.length,
      totalTrackedExposure: Math.round(totalTrackedExposure * 100) / 100,
      lastRefreshed: new Date().toISOString(),
    },
    ideas,
    walletResults,
    walletScores,
    validationErrors: [],
  };
}

"use client";

import { useCallback, useSyncExternalStore } from "react";
import { EMPTY_PORTFOLIO, PortfolioStateSchema, type PortfolioState, type Trade } from "@/lib/portfolio/types";

const STORAGE_KEY = "polymarket-smart-money:portfolio";

const listeners = new Set<() => void>();

function emitChange(): void {
  for (const listener of listeners) listener();
}

function subscribe(callback: () => void): () => void {
  listeners.add(callback);
  window.addEventListener("storage", callback);
  return () => {
    listeners.delete(callback);
    window.removeEventListener("storage", callback);
  };
}

// Cached by raw string identity so useSyncExternalStore gets a stable
// reference when the underlying localStorage value hasn't actually changed.
let cachedRaw: string | null = null;
let cachedState: PortfolioState = EMPTY_PORTFOLIO;

function getSnapshot(): PortfolioState {
  const raw = window.localStorage.getItem(STORAGE_KEY);
  if (raw === cachedRaw) return cachedState;
  cachedRaw = raw;
  if (!raw) {
    cachedState = EMPTY_PORTFOLIO;
    return cachedState;
  }
  try {
    const parsed = PortfolioStateSchema.safeParse(JSON.parse(raw));
    cachedState = parsed.success ? parsed.data : EMPTY_PORTFOLIO;
  } catch {
    cachedState = EMPTY_PORTFOLIO;
  }
  return cachedState;
}

function getServerSnapshot(): PortfolioState {
  return EMPTY_PORTFOLIO;
}

function writeToStorage(state: PortfolioState): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // localStorage can throw in private-browsing / quota-exceeded cases; non-fatal.
  }
  emitChange();
}

export function usePortfolio() {
  const portfolio = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

  const setStartingBankroll = useCallback((amountUsd: number) => {
    const current = getSnapshot();
    writeToStorage({
      ...current,
      startingBankrollUsd: amountUsd,
      startingBankrollSetAt: new Date().toISOString(),
    });
  }, []);

  const addTrade = useCallback((trade: Trade) => {
    const current = getSnapshot();
    writeToStorage({ ...current, trades: [trade, ...current.trades] });
  }, []);

  const updateTrade = useCallback((id: string, patch: Partial<Trade>) => {
    const current = getSnapshot();
    writeToStorage({
      ...current,
      trades: current.trades.map((t) => (t.id === id ? { ...t, ...patch } : t)),
    });
  }, []);

  const deleteTrade = useCallback((id: string) => {
    const current = getSnapshot();
    writeToStorage({ ...current, trades: current.trades.filter((t) => t.id !== id) });
  }, []);

  const resetPortfolio = useCallback(() => {
    writeToStorage(EMPTY_PORTFOLIO);
  }, []);

  return { portfolio, setStartingBankroll, addTrade, updateTrade, deleteTrade, resetPortfolio };
}

"use client";

import { useCallback, useSyncExternalStore } from "react";

const STORAGE_KEY = "polymarket-smart-money:recent-wallet-lists";
const MAX_ENTRIES = 8;

export interface RecentWalletList {
