import { fetchJson } from "./http";
import {
  RawActivityResponseSchema,
  RawPositionsResponseSchema,
  type RawActivity,
  type RawPosition,
} from "../types";

const DATA_API_BASE = "https://data-api.polymarket.com";

/** Fetches a wallet's current positions (paginated, capped at a few pages). */
export async function fetchWalletPositions(
  wallet: string,
): Promise<RawPosition[]> {
  const positions: RawPosition[] = [];
  const limit = 500;
  let offset = 0;
  const maxPages = 4; // hard cap so one huge wallet can't stall the batch

  for (let page = 0; page < maxPages; page++) {
    const url = `${DATA_API_BASE}/positions?user=${wallet}&limit=${limit}&offset=${offset}&sizeThreshold=0`;
    const raw = await fetchJson<unknown>(url, { timeoutMs: 12_000 });
    const parsed = RawPositionsResponseSchema.safeParse(raw);
    if (!parsed.success) {
      throw new Error(
        `Unexpected /positions response shape for ${wallet}: ${parsed.error.message}`,
      );
    }
    positions.push(...parsed.data);
    if (parsed.data.length < limit) break;
    offset += limit;
  }

  return positions;
}

/** Fetches a wallet's most recent activity, used to derive last-active timestamps per market. */
export async function fetchWalletActivity(
  wallet: string,
  limit = 500,
): Promise<RawActivity[]> {
  const url = `${DATA_API_BASE}/activity?user=${wallet}&limit=${limit}&sortBy=TIMESTAMP&sortDirection=DESC`;
  const raw = await fetchJson<unknown>(url, { timeoutMs: 12_000 });
  const parsed = RawActivityResponseSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(
      `Unexpected /activity response shape for ${wallet}: ${parsed.error.message}`,
    );
  }
  return parsed.data;
}

import { fetchJson, mapWithConcurrencyLimit } from "./http";
import { RawGammaMarketSchema, type RawGammaMarket } from "../types";

const GAMMA_API_BASE = "https://gamma-api.polymarket.com";
const CHUNK_SIZE = 50;
const CHUNK_CONCURRENCY = 6;

/**
 * Fetches Gamma market metadata (active/closed status, liquidity, volume,
 * spread, tags, slug) for a batch of condition IDs. Chunked to keep query
 * strings reasonable, and chunks are fetched with bounded concurrency —
 * at large wallet-list scale (hundreds of distinct markets across many
 * wallets) this stage would otherwise become a sequential bottleneck.
 */
export async function fetchMarketsByConditionIds(
  conditionIds: string[],
): Promise<Map<string, RawGammaMarket>> {
  const byCondition = new Map<string, RawGammaMarket>();
  const uniqueIds = Array.from(new Set(conditionIds));

  const chunks: string[][] = [];
  for (let i = 0; i < uniqueIds.length; i += CHUNK_SIZE) {
    chunks.push(uniqueIds.slice(i, i + CHUNK_SIZE));
  }

  const settled = await mapWithConcurrencyLimit(chunks, CHUNK_CONCURRENCY, async (chunk) => {
    const params = chunk
      .map((id) => `condition_ids=${encodeURIComponent(id)}`)
      .join("&");
    const url = `${GAMMA_API_BASE}/markets?${params}&limit=${CHUNK_SIZE}&include_tag=true`;
    // Market-metadata enrichment is best-effort; a failed chunk surfaces
    // missing data downstream as UNKNOWN liquidity/status rather than
    // failing the whole run.
    return fetchJson<unknown>(url, { timeoutMs: 12_000 });
  });

  for (const result of settled) {
    if (result.status !== "fulfilled" || !Array.isArray(result.value)) continue;
    for (const item of result.value) {
      const parsed = RawGammaMarketSchema.safeParse(item);
      if (!parsed.success) continue;
      const conditionId = parsed.data.conditionId;
      if (conditionId) byCondition.set(conditionId, parsed.data);
    }
  }

  return byCondition;
}

// Umbrella labels Polymarket actually uses for top-nav categorization,
// in priority order. A market carries many granular tags at once (e.g. a
// League of Legends match is tagged "Esports", "league of legends", "Games",
// "Sports" all at once) — this picks the broadest one so the dashboard's
// Category filter groups by the categories a user would actually recognize.
const CANONICAL_CATEGORIES = [
  "Sports",
  "Politics",
  "Elections",
  "Crypto",
  "Economy",
  "Business",
  "Pop Culture",
  "Science",
  "Entertainment",
  "Esports",
  "Tech",
  "World",
  "Weather",
];

/**
 * Derives a single display category from a Gamma market's tags. Requires
 * the market to have been fetched with `include_tag=true` — otherwise
 * `tags` is absent and this returns null (never fabricated).
 */
export function deriveCategory(market: RawGammaMarket): string | null {
  const labels = (market.tags ?? [])
    .map((t) => t.label)
    .filter((label): label is string => Boolean(label));
  if (labels.length === 0) return null;

  const labelSet = new Set(labels.map((l) => l.toLowerCase()));
  for (const canonical of CANONICAL_CATEGORIES) {
    if (labelSet.has(canonical.toLowerCase())) return canonical;
  }
  return labels[0];
}

// Per-category subcategory groups. Each canonical name lists the real tag
// labels Polymarket uses that should map to it, verified live against
// gamma-api.polymarket.com/events (e.g. college football markets carry
// both "CFB" and "NCAAF" tags simultaneously — they must collapse to one
// bucket, not split the same league across two subcategory filters).
const SUBCATEGORY_GROUPS: Record<string, { canonical: string; aliases: string[] }[]> = {
  Sports: [
    { canonical: "NFL", aliases: ["nfl"] },
    { canonical: "NBA", aliases: ["nba"] },
    { canonical: "WNBA", aliases: ["wnba"] },
    { canonical: "MLB", aliases: ["mlb"] },
    { canonical: "NHL", aliases: ["nhl"] },
    { canonical: "CFB", aliases: ["cfb", "ncaaf", "ncaa football", "college football"] },
    { canonical: "College Basketball", aliases: ["ncaab", "college basketball", "march madness"] },
    { canonical: "Soccer", aliases: ["soccer", "premier league", "champions league", "la liga", "fifa", "mls"] },
    { canonical: "UFC/MMA", aliases: ["ufc", "mma"] },
    { canonical: "Boxing", aliases: ["boxing"] },
    { canonical: "Tennis", aliases: ["tennis", "atp", "wta"] },
    { canonical: "Golf", aliases: ["golf", "pga"] },
    { canonical: "Formula 1", aliases: ["formula 1", "f1"] },
    { canonical: "NASCAR", aliases: ["nascar"] },
    { canonical: "Esports", aliases: ["esports", "league of legends", "lol", "cs2", "valorant", "dota 2"] },
    { canonical: "Olympics", aliases: ["olympics"] },
    { canonical: "Cricket", aliases: ["cricket"] },
    { canonical: "Rugby", aliases: ["rugby"] },
  ],
  Politics: [
    { canonical: "US Elections", aliases: ["us politics", "elections", "senate", "house", "congress"] },
    { canonical: "World Elections", aliases: ["world elections", "global elections"] },
    { canonical: "Geopolitics", aliases: ["geopolitics", "war"] },
  ],
  Crypto: [
    { canonical: "Bitcoin", aliases: ["bitcoin", "btc"] },
    { canonical: "Ethereum", aliases: ["ethereum", "eth"] },
    { canonical: "Altcoins", aliases: ["altcoins", "solana", "sol"] },
  ],
  Economy: [
    { canonical: "Fed", aliases: ["fed", "federal reserve", "interest rates"] },
    { canonical: "Inflation", aliases: ["inflation", "cpi"] },
  ],
};

/**
 * Derives a subcategory (e.g. Sports > MLB) from a market's tags, scoped to
 * its already-derived top-level category. Requires `include_tag=true` data
 * like `deriveCategory`. Returns null if the top category has no configured
 * subcategory groups, or none of its tags match a known league/topic — never
 * fabricated from an unverified guess.
 */
export function deriveSubcategory(market: RawGammaMarket, topCategory: string | null): string | null {
  if (!topCategory) return null;
  const groups = SUBCATEGORY_GROUPS[topCategory];
  if (!groups) return null;

  const labels = new Set(
    (market.tags ?? [])
      .map((t) => t.label?.toLowerCase())
      .filter((label): label is string => Boolean(label)),
  );

  for (const group of groups) {
    if (group.aliases.some((alias) => labels.has(alias))) return group.canonical;
  }
  return null;
}

export function parseNumeric(
  value: string | number | undefined | null,
): number | null {
  if (value === undefined || value === null) return null;
  const n = typeof value === "number" ? value : Number.parseFloat(value);
  return Number.isFinite(n) ? n : null;
}

export function parseOutcomesArray(
  value: string | string[] | undefined,
): string[] {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export interface FetchJsonOptions {
  timeoutMs?: number;
  retries?: number;
  retryDelayMs?: number;
}

export class ApiError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Fetches JSON with a timeout and exponential backoff retry on transient
 * failures (network errors, timeouts, 429, 5xx). Does not retry on 4xx
 * (other than 429) since those indicate a bad request/address.
 */
export async function fetchJson<T>(
  url: string,
  options: FetchJsonOptions = {},
): Promise<T> {
  const { timeoutMs = 10_000, retries = 2, retryDelayMs = 500 } = options;

  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const res = await fetch(url, {
        signal: controller.signal,
        headers: { Accept: "application/json" },
      });
      clearTimeout(timer);

      if (!res.ok) {
        const retriable = res.status === 429 || res.status >= 500;
        if (retriable && attempt < retries) {
          await sleep(retryDelayMs * 2 ** attempt);
          continue;
        }
        throw new ApiError(
          `Request to ${url} failed with status ${res.status}`,
          res.status,
        );
      }

      return (await res.json()) as T;
    } catch (err) {
      clearTimeout(timer);
      lastError = err;
      const isAbort = err instanceof DOMException && err.name === "AbortError";
      const isApiError = err instanceof ApiError;
      const retriable = isAbort || !isApiError;
      if (retriable && attempt < retries) {
        await sleep(retryDelayMs * 2 ** attempt);
        continue;
      }
      break;
    }
  }

  if (lastError instanceof ApiError) throw lastError;
  if (lastError instanceof DOMException && lastError.name === "AbortError") {
    throw new ApiError(`Request to ${url} timed out`);
  }
  throw new ApiError(
    `Request to ${url} failed: ${lastError instanceof Error ? lastError.message : String(lastError)}`,
  );
}

/**
 * Runs async tasks with a bounded concurrency limit, preserving input order
 * in the returned settled results (never throws — each task's outcome is
 * captured individually so one failure can't abort the batch).
 */
export async function mapWithConcurrencyLimit<T, R>(
  items: T[],
  limit: number,
  worker: (item: T, index: number) => Promise<R>,
): Promise<PromiseSettledResult<R>[]> {
  const results: PromiseSettledResult<R>[] = new Array(items.length);
  let cursor = 0;

  async function runNext(): Promise<void> {
    while (cursor < items.length) {
      const index = cursor++;
      try {
        const value = await worker(items[index], index);
        results[index] = { status: "fulfilled", value };
      } catch (reason) {
        results[index] = { status: "rejected", reason };
      }
    }
  }

  const workers = Array.from(
    { length: Math.min(limit, items.length) },
    () => runNext(),
  );
  await Promise.all(workers);
  return results;
}

import type { RawActivity, RawGammaMarket, RawPosition, NormalizedPosition } from "../types";
import { deriveCategory, deriveSubcategory, parseNumeric } from "./gamma-api";

/**
 * Builds a per-wallet map of conditionId -> most recent activity timestamp
 * (seconds), used to derive position freshness since /positions has no
 * last-touched field of its own.
 */
export function buildLastActivityIndex(
  activity: RawActivity[],
): Map<string, number> {
  const index = new Map<string, number>();
  for (const entry of activity) {
    const existing = index.get(entry.conditionId);
    if (!existing || entry.timestamp > existing) {
      index.set(entry.conditionId, entry.timestamp);
    }
  }
  return index;
}

/**
 * Converts raw /positions rows into normalized positions, filtering out
 * anything below `minValueUsd` and enriching with Gamma market status
 * (active/closed) and last-activity timestamps.
 *
 * Yes/No (and other outcome indices) are never merged — each outcome index
 * within a conditionId remains a distinct row so opposing directional bets
 * are never collapsed into one.
 */
export function normalizePositions(
  wallet: string,
  rawPositions: RawPosition[],
  marketsByCondition: Map<string, RawGammaMarket>,
  lastActivityByCondition: Map<string, number>,
  minValueUsd: number,
): { positions: NormalizedPosition[]; totalRawCount: number } {
  const positions: NormalizedPosition[] = [];

  for (const raw of rawPositions) {
    if (raw.currentValue < minValueUsd) continue;

    const market = marketsByCondition.get(raw.conditionId);
    const isActiveMarket = market
      ? market.active === true && market.closed !== true
      : true; // unknown status: don't silently drop, but don't claim it's "confirmed active" either

    if (market && market.closed === true) continue;

    const category = market ? deriveCategory(market) : null;

    positions.push({
      wallet,
      conditionId: raw.conditionId,
      asset: raw.asset,
      marketSlug: raw.slug ?? market?.slug ?? null,
      eventSlug: raw.eventSlug ?? null,
      eventTitle: raw.title,
      marketQuestion: market?.question ?? raw.title,
      outcome: raw.outcome,
      outcomeIndex: raw.outcomeIndex,
      currentProbability: raw.curPrice,
      avgEntryPrice: raw.avgPrice,
      sizeShares: raw.size,
      currentValue: raw.currentValue,
      cashPnl: raw.cashPnl,
      percentPnl: raw.percentPnl,
      lastActivityTs: lastActivityByCondition.get(raw.conditionId) ?? null,
      isActiveMarket,
      category,
      subCategory: market ? deriveSubcategory(market, category) : null,
      endDate: raw.endDate ?? market?.endDate ?? null,
    });
  }

  return { positions, totalRawCount: rawPositions.length };
}

export interface MarketQuoteInfo {
  liquidity: number | null;
  volume: number | null;
  spread: number | null;
  polymarketUrl: string | null;
}

export function extractMarketQuoteInfo(
  market: RawGammaMarket | undefined,
  eventSlug: string | null,
  marketSlug: string | null,
): MarketQuoteInfo {
  const liquidity = parseNumeric(market?.liquidity);
  const volume = parseNumeric(market?.volume);
  const spread = parseNumeric(market?.spread);
  const slugForUrl = eventSlug ?? marketSlug ?? market?.slug ?? null;
  const polymarketUrl = slugForUrl
    ? `https://polymarket.com/event/${slugForUrl}`
    : null;
  return { liquidity, volume, spread, polymarketUrl };
}

const ADDRESS_RE = /^0x[a-fA-F0-9]{40}$/;

export interface ParsedWallets {
  valid: string[]; // de-duplicated, lowercased, in first-seen order
  invalid: string[]; // original malformed tokens, in first-seen order
  duplicates: string[]; // original tokens that repeated a prior valid entry
}

/**
 * Parses a wallet-list textarea value into valid/invalid/duplicate buckets.
 * Accepts newline- and/or comma-separated Polygon addresses (0x + 40 hex chars).
 */
export function parseWalletInput(raw: string): ParsedWallets {
  const tokens = raw
    .split(/[\n,]/)
    .map((t) => t.trim())
    .filter((t) => t.length > 0);

  const valid: string[] = [];
  const invalid: string[] = [];
  const duplicates: string[] = [];
  const seen = new Set<string>();

  for (const token of tokens) {
    if (!ADDRESS_RE.test(token)) {
      invalid.push(token);
      continue;
    }
    const normalized = token.toLowerCase();
    if (seen.has(normalized)) {
      duplicates.push(token);
      continue;
    }
    seen.add(normalized);
    valid.push(normalized);
  }

  return { valid, invalid, duplicates };
}

/**
 * Rewrites a wallet-list textarea value with exact-duplicate addresses
 * removed (case-insensitive, first occurrence kept). Invalid/malformed
 * tokens are left untouched, in place, so the user can still see and fix
 * them — this only removes true duplicates of a valid address.
 */
export function dedupeWalletInput(raw: string): string {
  const tokens = raw
    .split(/[\n,]/)
    .map((t) => t.trim())
    .filter((t) => t.length > 0);

  const seen = new Set<string>();
  const output: string[] = [];

  for (const token of tokens) {
    if (!ADDRESS_RE.test(token)) {
      output.push(token);
      continue;
    }
    const normalized = token.toLowerCase();
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    output.push(token);
  }

  return output.join("\n");
}

export function isValidWalletAddress(value: string): boolean {
  return ADDRESS_RE.test(value.trim());
}

export function shortenAddress(address: string, chars = 4): string {
  if (address.length <= chars * 2 + 2) return address;
  return `${address.slice(0, chars + 2)}…${address.slice(-chars)}`;
}

import type { BankrollSummary, EquityCurvePoint, PortfolioState, Trade, TradePnl } from "./types";

/**
 * Computes a single trade's shares and PnL. Polymarket outcome shares pay
 * out $1 each if the outcome resolves YES for that side (`won`) and $0 if
 * it resolves the other way (`lost`); a `sold` trade exits early at
 * `exitPriceCents` instead of waiting for resolution.
 */
export function computeTradePnl(trade: Trade): TradePnl {
  const shares = trade.stakeUsd / (trade.entryPriceCents / 100);
  const costBasis = trade.stakeUsd;

  if (trade.status === "won") {
    return { shares, realizedPnl: shares * 1 - costBasis, unrealizedPnl: null, costBasis };
  }
  if (trade.status === "lost") {
    return { shares, realizedPnl: -costBasis, unrealizedPnl: null, costBasis };
  }
  if (trade.status === "sold") {
    const exitCents = trade.exitPriceCents ?? 0;
    return { shares, realizedPnl: shares * (exitCents / 100) - costBasis, unrealizedPnl: null, costBasis };
  }

  // open
  const unrealizedPnl =
    trade.currentPriceCents !== null ? shares * (trade.currentPriceCents / 100) - costBasis : null;
  return { shares, realizedPnl: null, unrealizedPnl, costBasis };
}

export function summarizePortfolio(portfolio: PortfolioState): BankrollSummary {
  let realizedPnl = 0;
  let unrealizedPnl = 0;
  let committedStakeUsd = 0;
  let wins = 0;
  let losses = 0;
  let openTrades = 0;
  let closedTrades = 0;
  let totalStaked = 0;

  for (const trade of portfolio.trades) {
    const pnl = computeTradePnl(trade);
    totalStaked += trade.stakeUsd;

    if (trade.status === "open") {
      openTrades += 1;
      committedStakeUsd += trade.stakeUsd;
      unrealizedPnl += pnl.unrealizedPnl ?? 0;
    } else {
      closedTrades += 1;
      realizedPnl += pnl.realizedPnl ?? 0;
      if (trade.status === "won") wins += 1;
      if (trade.status === "lost") losses += 1;
    }
  }

  const resolvedCount = wins + losses;
  const hasStartingBankroll = portfolio.startingBankrollUsd !== null;
  // currentBankrollUsd is mark-to-market net worth (includes committed
  // capital's current value); availableBankrollUsd is free cash you could
  // actually stake on a new trade right now. These are deliberately
  // different numbers — collapsing them into one hid how much capital was
  // already tied up in open positions.
  const currentBankrollUsd = hasStartingBankroll
    ? portfolio.startingBankrollUsd! + realizedPnl + unrealizedPnl
    : null;
  const availableBankrollUsd = hasStartingBankroll
    ? portfolio.startingBankrollUsd! + realizedPnl - committedStakeUsd
    : null;

  return {
    startingBankrollUsd: portfolio.startingBankrollUsd,
    currentBankrollUsd,
    availableBankrollUsd,
    committedStakeUsd,
    realizedPnl,
    unrealizedPnl,
    totalTrades: portfolio.trades.length,
    openTrades,
    closedTrades,
    wins,
    losses,
    winRate: resolvedCount > 0 ? wins / resolvedCount : null,
    totalStaked,
  };
}

/**
 * Cumulative bankroll over time, one point per closed trade (in
 * chronological order by `closedAt`), starting from the starting bankroll.
 * Open trades don't move the curve since their PnL isn't realized yet.
 */
export function buildEquityCurve(portfolio: PortfolioState): EquityCurvePoint[] {
  if (portfolio.startingBankrollUsd === null) return [];

  const closedTrades = portfolio.trades
    .filter((t) => t.status !== "open" && t.closedAt !== null)
    .sort((a, b) => new Date(a.closedAt!).getTime() - new Date(b.closedAt!).getTime());

  const points: EquityCurvePoint[] = [
    {
      label: portfolio.startingBankrollSetAt ?? new Date(0).toISOString(),
      bankroll: portfolio.startingBankrollUsd,
    },
  ];

  let running = portfolio.startingBankrollUsd;
  for (const trade of closedTrades) {
    const pnl = computeTradePnl(trade);
    running += pnl.realizedPnl ?? 0;
    points.push({ label: trade.closedAt!, bankroll: Math.round(running * 100) / 100 });
  }

  return points;
}

