}

export interface AnalyzeRequestOptions {
  minValueUsd: number;
  weighting: "quality" | "equal";
}

// ---------------------------------------------------------------------------
// Request validation schema
// ---------------------------------------------------------------------------

/**
 * No per-run wallet cap — analyze as many wallets as you paste. The array
 * max here is purely a sanity ceiling against malformed/malicious payloads
 * (e.g. a multi-megabyte body), not a real usage limit; ordinary lists of
 * any practical size stay far under it.
 */
export const AnalyzeRequestSchema = z.object({
  wallets: z.array(z.string()).min(1).max(20_000),
  minValueUsd: z.number().min(0).max(100000).default(100),
  weighting: z.enum(["quality", "equal"]).default("quality"),
});
export type AnalyzeRequestBody = z.infer<typeof AnalyzeRequestSchema>;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

export function formatUsd(value: number | null, opts: { compact?: boolean } = {}): string {
  if (value === null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: value >= 1000 ? 0 : 2,
    notation: opts.compact ? "compact" : "standard",
  }).format(value);
}

export function formatPct(fraction: number, digits = 0): string {
  return `${(fraction * 100).toFixed(digits)}%`;
}

export function formatCents(probability: number): string {
  return `${Math.round(probability * 100)}¢`;
}

/**
 * Validates a user-supplied URL before it's ever used as an href, blocking
 * javascript:/data: injection. Only http(s) survive.
 */
export function safeExternalUrl(value: string | null | undefined): string | undefined {
  if (!value) return undefined;
  try {
    const parsed = new URL(value);
    if (parsed.protocol === "http:" || parsed.protocol === "https:") return value;
  } catch {
    return undefined;
  }
  return undefined;
}

export function formatRelativeTime(tsSeconds: number | null, nowMs = Date.now()): string {
  if (tsSeconds === null) return "Unknown";
  const diffMs = nowMs - tsSeconds * 1000;
  const diffMin = Math.round(diffMs / 60_000);
  if (diffMin < 1) return "just now";
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHr = Math.round(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h ago`;
  const diffDay = Math.round(diffHr / 24);
  return `${diffDay}d ago`;
}

import { NextRequest } from "next/server";
import { runAnalysis } from "@/lib/analyze";
import { AnalyzeRequestSchema } from "@/lib/types";
import { parseWalletInput } from "@/lib/polymarket/wallets";

export const dynamic = "force-dynamic";

type StreamEvent =
  | { type: "progress"; loaded: number; total: number }
  | { type: "result"; data: unknown }
  | { type: "error"; message: string };

function encodeEvent(event: StreamEvent): Uint8Array {
  return new TextEncoder().encode(JSON.stringify(event) + "\n");
}

export async function POST(request: NextRequest) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Request body must be valid JSON." }, { status: 400 });
  }

  const parsedBody = AnalyzeRequestSchema.safeParse(body);
  if (!parsedBody.success) {
    const firstIssue = parsedBody.error.issues[0];
    const detail = firstIssue
      ? `${firstIssue.path.join(".") || "request"}: ${firstIssue.message}`
      : "Request did not match the expected shape.";
    return Response.json(
      { error: `Invalid request — ${detail}`, issues: parsedBody.error.issues },
      { status: 400 },
    );
  }

  const { wallets: rawWalletLines, minValueUsd, weighting } = parsedBody.data;
  const parsed = parseWalletInput(rawWalletLines.join("\n"));

  const validationErrors: string[] = [];
  if (parsed.invalid.length > 0) {
    validationErrors.push(
      `Ignored ${parsed.invalid.length} invalid entr${parsed.invalid.length === 1 ? "y" : "ies"}: ${parsed.invalid.slice(0, 10).join(", ")}${parsed.invalid.length > 10 ? "…" : ""}`,
    );
  }
  if (parsed.duplicates.length > 0) {
    validationErrors.push(
      `Ignored ${parsed.duplicates.length} duplicate wallet${parsed.duplicates.length === 1 ? "" : "s"}.`,
    );
  }

  if (parsed.valid.length === 0) {
    return Response.json(
      {
        error: "No valid Polygon wallet addresses found in input.",
        validationErrors,
      },
      { status: 400 },
    );
  }

  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      try {
        const result = await runAnalysis(
          parsed.valid,
          { minValueUsd, weighting },
          (loaded, total) => {
            controller.enqueue(encodeEvent({ type: "progress", loaded, total }));
          },
        );
        result.validationErrors = validationErrors;
        controller.enqueue(encodeEvent({ type: "result", data: result }));
      } catch (err) {
        const message = err instanceof Error ? err.message : "Analysis failed unexpectedly.";
        controller.enqueue(encodeEvent({ type: "error", message }));
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}

